    "result-v3": {
      "type": "object",
      "properties": {
        "resultId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]+$",
          "minLength": 1,
          "maxLength": 160
        },
        "itemId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]+$",
          "minLength": 1,
          "maxLength": 160
        },
        "sourceSnapshotHash": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "status": {
          "enum": [
            "valued",
            "needs-review",
            "unidentified"
          ]
        },
        "identification": {
          "$ref": "#/definitions/identification"
        },
        "valuation": {
          "anyOf": [
            {
              "$ref": "#/definitions/estimate"
            },
            {
              "type": "null"
            }
          ]
        },
        "comparables": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/comparable-v3"
          },
          "maxItems": 50
        },
        "warnings": {
          "type": "array",
          "items": {
            "type": "string",
            "maxLength": 2000
          },
          "maxItems": 50
        },
        "supersedesResultId": {
          "anyOf": [
            {
              "type": "string",
              "pattern": "^[A-Za-z0-9_-]+$",
              "minLength": 1,
              "maxLength": 160
            },
            {
              "type": "null"
            }
          ]
        },
        "pricing": {
          "anyOf": [
            {
              "$ref": "#/definitions/pricing-evidence"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "resultId",
        "itemId",
        "sourceSnapshotHash",
        "status",
        "identification",
        "valuation",
        "comparables",
        "warnings",
        "supersedesResultId",
        "pricing"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "valued"
              }
            }
          },
          "then": {
            "properties": {
              "valuation": {
                "$ref": "#/definitions/estimate"
              },
              "comparables": {
                "minItems": 1
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "status": {
                "const": "unidentified"
              }
            }
          },
          "then": {
            "properties": {
              "valuation": {
                "type": "null"
              }
            }
          }
        }
      ]
    },
